    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);
        uint before = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(c.depositsCount() == before && address(c).balance == 0);
    }
    receive() external payable {}
}

